import * as T from './three.module.js';import {roadSurface,roadMarkings,PARKINGS} from './road-layout.js?v=detail18';
export function buildRoads(scene){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(roadSurface(),3));geo.computeVertexNormals();const surface=new T.Mesh(geo,new T.MeshStandardMaterial({color:'#555d5d',roughness:.97}));surface.name='Continuous county and regional asphalt';surface.receiveShadow=true;scene.add(surface);for(const p of PARKINGS){const m=new T.Mesh(new T.BoxGeometry(p.w,.045,p.d),surface.material);m.name=p.name;m.position.set(p.x,.251,p.z);scene.add(m);}const lines=roadMarkings();for(const p of PARKINGS)for(let i=0;i<Math.floor(p.w/2.7);i++){const x=p.x-p.w/2+i*2.7;lines.push({x,z:p.z,w:.08,d:p.d-1},{x:x+1.3,z:p.z+p.d/2-1,w:2.6,d:.08});}const batch=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#eee7ca',roughness:.9}),lines.length),dummy=new T.Object3D();batch.name='County road batch';lines.forEach((r,i)=>{dummy.position.set(r.x,.278,r.z);dummy.scale.set(r.w,.012,r.d);dummy.updateMatrix();batch.setMatrixAt(i,dummy.matrix);});batch.computeBoundingSphere();scene.add(batch);return {surface,batch};}
